@Component("payrollRun-handler")
@ProcessingGroup("payrollRun-processing-group")
public class PayrollRunEventHandler {
	
	// core constructor
	PayrollRunEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePayrollRunEvent
     */
    @EventHandler
    public void handle( CreatePayrollRunEvent event) {
        entityManager.persist(new PayrollRun(event.getPayrollRunId(), event.getRunNumber(), event.getPeriodStart(), event.getPeriodEnd(), event.getPaymentDate(), event.getPayrollCalendar(), event.getPayrollItems(), event.getStatus()));
    }

    /*
     * @param	event UpdatePayrollRunEvent
     */
    @EventHandler
    public PayrollRun handle( UpdatePayrollRunEvent event) {
    	entityManager.merge(new PayrollRun(event.getPayrollRunId(), event.getRunNumber(), event.getPeriodStart(), event.getPeriodEnd(), event.getPaymentDate(), event.getPayrollCalendar(), event.getPayrollItems(), event.getStatus()));
    }
    
    /*
     * @param	event DeletePayrollRunEvent
     */
    @EventHandler
    public void on( DeletePayrollRunEvent event) {
    	PayrollRun entity = new PayrollRun();
   
    	// ------------------------------------------
    	// apply the PayrollRunId
    	// ------------------------------------------
    	entity.setPayrollRunId( event.getPayrollRunId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PayrollRunRepository payrollRunEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PayrollRunEventHandler.class.getName());

}
